int main() {
    long long n, m;
    cin >> n >> m;

    long long q = n / m;
    long long r = n % m;

    long long a = r * q * (q + 1) / 2
                + (m - r) * q * (q - 1) / 2;
    long long b = (n - m + 1) * (n - m) / 2;

    cout << a << ' ' << b << '\n';
    return 0;
}

